const { OpenFeature } = require('@openfeature/server-sdk');

async function processPayment(user, order) {
  const client = OpenFeature.getClient();
  const isStripeV3Enabled = await client.getBooleanValue('stripe-v3-checkout', false, { userId: user.id });

  if (isStripeV3Enabled) {
    return executeStripeV3Payment(user, order);
